CREATE   PROCEDURE [synapse_ce].[usp_Insert_team]
AS
BEGIN
	INSERT INTO [synapse_ce].[team]
	(
		[administratorid],
		[administratorid_entitytype],
		[administratoridname],
		[administratoridyominame],
		[apitil_itsmteam],
		[apitil_levelitsm],
		[apitil_notifyonassign],
		[apitil_notifyoncreate],
		[apitil_notifyonescalation],
		[apitil_notifyonslastatuschange],
		[apitil_notifyonstatuschange],
		[apitil_notifyonupdate],
		[apitil_outgoingitsmemailqueue],
		[apitil_outgoingitsmemailqueue_entitytype],
		[apitil_outgoingitsmemailqueuename],
		[apuk_teammanagerid],
		[apuk_teammanagerid_entitytype],
		[apuk_teammanageridname],
		[apuk_teammanageridyominame],
		[azureactivedirectoryobjectid],
		[businessunitid],
		[businessunitid_entitytype],
		[businessunitidname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[emailaddress],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[isdefault],
		[issastokenset],
		[membershiptype],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[msdynmkt_associatedevent],
		[msdynmkt_associatedevent_entitytype],
		[msdynmkt_associatedeventname],
		[name],
		[organizationid],
		[organizationidname],
		[overriddencreatedon],
		[processid],
		[queueid],
		[queueid_entitytype],
		[queueidname],
		[regardingobjectid],
		[regardingobjectid_entitytype],
		[regardingobjecttypecode],
		[sastoken],
		[sharelinkqualifier],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[stageid],
		[systemmanaged],
		[teamid],
		[teamtemplateid],
		[teamtemplateid_entitytype],
		[teamtype],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[traversedpath],
		[versionnumber],
		[yominame]
	)
	SELECT 
		stg.[administratorid],
		stg.[administratorid_entitytype],
		stg.[administratoridname],
		stg.[administratoridyominame],
		stg.[apitil_itsmteam],
		stg.[apitil_levelitsm],
		stg.[apitil_notifyonassign],
		stg.[apitil_notifyoncreate],
		stg.[apitil_notifyonescalation],
		stg.[apitil_notifyonslastatuschange],
		stg.[apitil_notifyonstatuschange],
		stg.[apitil_notifyonupdate],
		stg.[apitil_outgoingitsmemailqueue],
		stg.[apitil_outgoingitsmemailqueue_entitytype],
		stg.[apitil_outgoingitsmemailqueuename],
		stg.[apuk_teammanagerid],
		stg.[apuk_teammanagerid_entitytype],
		stg.[apuk_teammanageridname],
		stg.[apuk_teammanageridyominame],
		stg.[azureactivedirectoryobjectid],
		stg.[businessunitid],
		stg.[businessunitid_entitytype],
		stg.[businessunitidname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[emailaddress],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[isdefault],
		stg.[issastokenset],
		stg.[membershiptype],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[msdynmkt_associatedevent],
		stg.[msdynmkt_associatedevent_entitytype],
		stg.[msdynmkt_associatedeventname],
		stg.[name],
		stg.[organizationid],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[processid],
		stg.[queueid],
		stg.[queueid_entitytype],
		stg.[queueidname],
		stg.[regardingobjectid],
		stg.[regardingobjectid_entitytype],
		stg.[regardingobjecttypecode],
		stg.[sastoken],
		stg.[sharelinkqualifier],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[stageid],
		stg.[systemmanaged],
		stg.[teamid],
		stg.[teamtemplateid],
		stg.[teamtemplateid_entitytype],
		stg.[teamtype],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[traversedpath],
		stg.[versionnumber],
		stg.[yominame]	
	FROM [staging_ce].[team] stg
		LEFT JOIN [synapse_ce].[team] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
